SELECT country, CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(STDDEV(rating), 2) AS stddev_rating, COUNT(CASE WHEN city = 'Bangkok' THEN 1 END) AS bangkok_count FROM suppliers GROUP BY country, CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END HAVING COUNT(CASE WHEN city = 'Bangkok' THEN 1 END) >= 1 ORDER BY bangkok_count DESC;
